mapper.select:

WHERE s.is_deleted = false
AND p.status = 'ENABLED' AND s.status = 'ENABLED'

    AND s.reference_sale_price IS NOT NULL AND s.reference_sale_currency IN ('CNY', 'TWD')
    AND s.reference_sale_currency = #{referenceSaleCurrency}

AND p.status = #{query.status}
AND s.status = #{query.skuStatus}

    AND s.id = #{query.skuId}

AND p.id = #{query.productId}

    AND p.category_id IN
    #{id}


    AND (p.name ILIKE CONCAT('%', #{query.keyword}, '%') OR p.code ILIKE CONCAT('%', #{query.keyword}, '%')
        OR s.code ILIKE CONCAT('%', #{query.keyword}, '%') OR s.model ILIKE CONCAT('%', #{query.keyword}, '%'))


    AND EXISTS (
        SELECT 1 FROM product_sku_spec_value selection
        JOIN product_spec sp ON sp.id = selection.spec_id AND sp.is_deleted = false
        JOIN product_spec_value value ON value.id = selection.spec_value_id AND value.is_deleted = false
        WHERE selection.sku_id = s.id AND selection.is_deleted = false AND selection.spec_id = #{filter.specId}
        AND sp.value_type = 'TEXT' AND value.id = #{filter.specValueId}
        AND sp.value_type = 'NUMBER' AND value.number_value >= #{filter.minimum}
        AND sp.value_type = 'NUMBER' AND value.number_value <= #{filter.maximum}
    )

ORDER BY s.sort_order, s.id
